positoryId":949739368,"sha":"e4cf5e9b7a24f06ae05f11d4955fcfcd7d60e318"},{"author":{"account":{"login":"andiez02","providerType":"User"},"email":"ken1162004@gmail.com","name":"andiez02"},"authoredDate":"2026-10-07T17:15:29Z","committedDate":"2026-10-07T17:15:29Z","committer":{"account":{"login":"andiez02","providerType":"User"},"email":"ken1162004@gmail.com","name":"andiez02"},"observedAt":"2026-10-08T18:48:04.293Z","repositoryId":949739368,"sha":"f14bb4e14a92cf4f656cacd878fd1dca7adbf421"}],"observedAt":"2026-10-08T18:48:04.293Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/25797909?v=4","events_url":"https://api.github.com/users/phamtien1709/events{/privacy}","followers_url":"https://api.github.com/users/phamtien1709/followers","following_url":"https://api.github.com/users/phamtien1709/following{/other_user}","gists_url":"https://api.github.com/users/phamtien1709/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/phamtien1709","id":25797909,"login":"phamtien1709","node_id":"MDQ6VXNlcjI1Nzk3OTA5","organizations_url":"https://api.github.com/users/phamtien1709/orgs","received_events_url":"https://api.github.com/users/phamtien1709/received_events","repos_url":"https://api.github.com/users/phamtien1709/repos","site_admin":false,"starred_url":"https://api.github.com/users/phamtien1709/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/phamtien1709/subscriptions","type":"User","url":"https://api.github.com/users/phamtien1709","user_view_type":"public"},"comments_url":"https://api.github.com/repos/PoliceTeam/musicque/commits/91d61e3c97f8a6343801fbf24d51d42dcd6a00c6/comments","commit":{"author":{"date":"2026-10-08T12:20:29Z","email":"tien.pham@politetech.com","name":"Tian Lee"},"comment_count":0,"committer":{"date":"2026-10-08T12:20:29Z","email":"tien.pham@politetech.com","name":"Tian Lee"},"message":"feat(audition): render the waiting room and results in WebGL\n\n- Results: gold and silver podiums with spotlights and confetti for\n  ranks 1 and 2 (victory dances), everyone else on the floor (defeat).\n  Per-player stat boards are canvas textures in a drei Hud: rank, name,\n  total score, Perfect/Great/Cool/Bad/Missed and the longest Perfect\n  chain; top two get glowing gold/silver frames. 3D buttons return to\n  the waiting room or leave.\n- Waiting room: rebuilt as a WebGL panel (song/stage steppers, Del\n  toggle, bots, character chips, Ready/Start, copy link) from small\n  canvas-texture widgets; the camera shifts the stage left of it.\n- Track the longest Perfect chain (maxPerfect) on client and server.\n- Audio is fixed at 250ms latency, 40% music, 25% effects; the\n  settings controls are gone, only mute is remembered.\n- Name tags are canvas sprites; drop the dead HTML panels and CSS.","tree":{"sha":"42d0cec578b65fc5fe23637327e649887e201a6f","url":"https://api.github.com/repos/PoliceTeam/musicque/git/trees/42d0cec578b65fc5fe23637327e649887e201a6f"},"url":"https://api.github.com/repos/PoliceTeam/musicque/git/commits/91d61e3c97f8a6343801fbf24d51d42dcd6a00c6","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/25797909?v=4","events_url":"https://api.github.com/users/phamtien1709/events{/privacy}","followers_url":"https://api.github.com/users/phamtien1709/followers","following_url":"https://api.github.com/users/phamtien1709/following{/other_user}","gists_url":"https://api.github.com/users/phamtien1709/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/phamtien1709","id":25797909,"login":"phamtien1709","node_id":"MDQ6VXNlcjI1Nzk3OTA5","organizations_url":"https://api.github.com/users/phamtien1709/orgs","received_events_url":"https://api.github.com/users/phamtien1709/received_events","repos_url":"https://api.github.com/users/phamtien1709/repos","site_admin":false,"starred_url":"https://api.github.com/users/phamtien1709/starred{/owner}{/r